#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}


# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# Sets up "Logan staging": the Discord application the staging relay (staging.logit.land) and local dev run as, so they
# never share a bot with production. Writes its credentials to a private file local dev reads, and to the GitHub
# `staging` environment the staging deploy reads. The non-Discord secrets (TypeSafe, the relay's own keys) are the
# deploy wizard's job (scripts/setup-deploy.sh).

# Never inside a repo: the library defaults ENV_FILE to ./.env, so set it outright.
ENV_FILE="${RELAY_STAGING_ENV_FILE:-$HOME/.config/logitland/relay-staging.env}"
mkdir -p "$(dirname "$ENV_FILE")"
touch "$ENV_FILE" && chmod 600 "$ENV_FILE"

GUILD_ID=1562476123131093042  # logit.land but staging
GH_ENV=staging
# View Channels, Send Messages, Send Messages in Threads, Create Public and Private Threads, Manage Threads,
# Manage Webhooks, Manage Messages (takedowns), Manage Roles (people's roles), Read Message History,
# Embed Links, Attach Files, Add Reactions, Use Application Commands, Kick Members and Timeout Members (agents' own bots
# that post outside the relay).
BOT_PERMISSIONS=1497601535042
DEV_CALLBACK="http://${LOGITLAND_DEV_HOST:-10.0.3.2}:5174/auth/callback"

# env_secret NAME VALUE sets a secret on the GitHub `staging` environment, creating the environment the first time.
GH_ENV_READY=""
env_secret() {
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    # Created only when missing: a PUT on an existing environment would reset the rules setup-deploy.sh gives it.
    if [[ -z "$GH_ENV_READY" ]]; then
      gh api "repos/{owner}/{repo}/environments/$GH_ENV" >/dev/null 2>&1 || gh api -X PUT "repos/{owner}/{repo}/environments/$GH_ENV" >/dev/null
      GH_ENV_READY=1
    fi
    printf '%s' "$2" | gh secret set "$1" --env "$GH_ENV" >/dev/null
    printf '  %s✓ set%s %s on the GitHub %s environment\n' "$GREEN" "$RESET" "$1" "$GH_ENV"
  else
    warn "gh isn't signed in: set $1 on the GitHub $GH_ENV environment yourself (Settings → Environments → $GH_ENV)."
  fi
}

TOTAL_STAGES=5

banner "Logan staging"

stage "Application"
say "A second application in the Logitland team, so staging and local dev never act as production's Logan."
open_url "https://discord.com/developers/applications"
step "If you already made Logan staging, open it. Otherwise: New Application → name it Logan staging → Team: Logitland → Create."
step "On General Information, copy the Application ID."
ask DISCORD_APPLICATION_ID "Paste the Application ID:"
step "Copy the Public Key (just below it)."
ask DISCORD_PUBLIC_KEY "Paste the Public Key:"
step "Leave Interactions Endpoint URL empty: staging and local dev both answer /consent over the Gateway."
write_env DISCORD_APPLICATION_ID "$DISCORD_APPLICATION_ID"
write_env DISCORD_PUBLIC_KEY "$DISCORD_PUBLIC_KEY"
write_env DISCORD_GUILD_ID "$GUILD_ID"
env_secret DISCORD_APPLICATION_ID "$DISCORD_APPLICATION_ID"
env_secret DISCORD_PUBLIC_KEY "$DISCORD_PUBLIC_KEY"

stage "Bot"
open_url "https://discord.com/developers/applications/${DISCORD_APPLICATION_ID}/bot"
step "Set its username and avatar."
step "Turn OFF Public Bot."
step "Under Privileged Gateway Intents, turn ON Message Content Intent. Save Changes."
step "Reset Token → confirm → copy the token (shown once)."
ask_secret DISCORD_BOT_TOKEN "Paste the bot token (hidden):"
write_env DISCORD_BOT_TOKEN "$DISCORD_BOT_TOKEN"
env_secret DISCORD_BOT_TOKEN "$DISCORD_BOT_TOKEN"

stage "Sign-in with Discord (OAuth2)"
say "The staging dashboard and local dev sign people in through this application."
open_url "https://discord.com/developers/applications/${DISCORD_APPLICATION_ID}/oauth2"
step "Under Redirects, add both:"
step "  https://staging.logit.land/auth/callback"
step "  ${DEV_CALLBACK}"
step "Save Changes, then Reset Secret under Client Secret → copy it (shown once)."
ask_secret DISCORD_CLIENT_SECRET "Paste the client secret (hidden):"
write_env DISCORD_CLIENT_ID "$DISCORD_APPLICATION_ID"
write_env DISCORD_CLIENT_SECRET "$DISCORD_CLIENT_SECRET"
env_secret DISCORD_CLIENT_ID "$DISCORD_APPLICATION_ID"
env_secret DISCORD_CLIENT_SECRET "$DISCORD_CLIENT_SECRET"

stage "Add the bot to the staging server"
say "It asks for exactly the permissions the relay uses, on logit.land but staging only."
open_url "https://discord.com/oauth2/authorize?client_id=${DISCORD_APPLICATION_ID}&scope=bot+applications.commands&permissions=${BOT_PERMISSIONS}&guild_id=${GUILD_ID}&disable_guild_select=true"
step "Check the server is logit.land but staging, then Authorize."
step "Server Settings → Roles: drag its role just under textile, above every role it hands out (parent, clanker whisperer)."
step "Tell Claire it's in: she copies Logan's channel access (readme.md, staff.land, logit.lounge) to the new role."
pause "Done? Press Enter"

stage "Local dev"
say "pnpm dev reads this file when it exists, so local dev runs as Logan staging too."
if [[ -s "$HOME/.config/logitland/relay.env" ]] && [[ -z "$(_existing TYPESAFE_API_KEY || true)" ]]; then
  key=$(grep -E '^TYPESAFE_API_KEY=' "$HOME/.config/logitland/relay.env" | tail -n1 | cut -d= -f2- || true)
  if [[ -n "$key" ]]; then write_env TYPESAFE_API_KEY "$key"; else note "No TypeSafe key in relay.env; add TYPESAFE_API_KEY to $ENV_FILE yourself."; fi
fi
note "Restart pnpm dev to pick it up. Local dev and staging.logit.land now share one bot on one server: run dev while staging is quiet, or they'll both act."

finish
